			resp2, _, err := client.Exchange(req, "1.1.1.1:53")
			if err != nil {
				log.Println(err)
				return
			}
			// Check if the responses are the same
			if resp.Answer == resp2.Answer {
				// Store the hostname to IP in the map
				mu.Lock()
				ips[resp.Answer[0].Header.Name] = resp.Answer[0].Header.RrHeader.Attr.(*dns.A).A
				mu.Unlock()
				// Send the response back to the client
				w.WriteMsg(resp)
			} else {
				// Send the response back to the client
				w.WriteMsg(resp)
			}
		}()
	})

	// Start the DNS server
	log.Fatal(dns.ListenAndServe("0.0.0.0:53", nil))
}
